"use strict";
const plain = require("inner-plain");
const fenced = require("inner-fenced");

// A class that extends Promise: this module does not compile natively.
class Later extends Promise {}
exports.Later = Later;
exports.wait = (value) => new Later((resolve) => setTimeout(() => resolve(value * 2), 1));

exports.makePlain = (label) => new plain.Plain(label);
exports.plainInfo = (label) => plain.makeInfo(label);
exports.makeFenced = (label) => new fenced.Fenced(label);
exports.summarize = (p, f, info) => `${p.label}:${p.count} ${f.label}:${f.count} ${info.label}:${info.count}`;
